#!/usr/bin/env python3
"""Cards for the parts of the woman's model (data/anatomy_f) that had none, and the two "About this model" cards.
Writes data/nodes/body_female.json (listed in data/nodes/manifest.json). Facts are from the sources each card cites:
OpenStax Anatomy and Physiology 2e (sections 9.6, 11.3, 11.6, 19.1, 22.2, 23.3, 23.6, 27.2), the U.S. National Library of
Medicine's Visible Human Project page, the Human Reference Atlas pages of the female reference organs, and, where OpenStax does
not cover a structure, the Wikipedia articles named on the card (greater omentum, coccyx, liver segment, rectouterine pouch, uterine artery).
The prose is written for this site."""
import json, os

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
ANP = lambda sec, slug: ['ANP', sec, slug]
S272 = ANP('27.2', '27-2-anatomy-and-physiology-of-the-ovarian-reproductive-system')
S222 = ANP('22.2', '22-2-the-lungs')
S236 = ANP('23.6', '23-6-accessory-organs-in-digestion-the-liver-pancreas-and-gallbladder')
S233 = ANP('23.3', '23-3-the-mouth-pharynx-and-esophagus')
S96 = ANP('9.6', '9-6-anatomy-of-selected-synovial-joints')
S113 = ANP('11.3', '11-3-axial-muscles-of-the-head-neck-and-back')
S116 = ANP('11.6', '11-6-appendicular-muscles-of-the-pelvic-girdle-and-lower-limbs')
S191 = ANP('19.1', '19-1-heart-anatomy')
W = lambda t, u: {'title': t, 'url': u}
HRA_F = W('Human Reference Atlas: 3D reference organs, female (v1.10)', 'https://doi.org/10.48539/HBM637.DWBM.744')
VHP = W('U.S. National Library of Medicine: the Visible Human Project', 'https://www.nlm.nih.gov/research/visible/visible_human.html')

def card(id, title, kind, scale, parents, summary, basics, deeper, expert, facts, dyk=None, made_of=(), parts=(), related=(), refs=(), ext=(), cert='C1', oq=(), template='anatomy'):
    n = {'id': id, 'title': title, 'kind': kind, 'template': template, 'scale_m': scale, 'parents': list(parents), 'parts': list(parts), 'made_of': list(made_of),
         'processes': [], 'related': list(related), 'mesh': None, 'summary': summary, 'layers': {'basics': basics, 'deeper': deeper, 'expert': expert},
         'facts': [list(f) for f in facts], 'certainty': cert, 'refs': [list(r) for r in refs]}
    if dyk: n['did_you_know'] = dyk
    if ext: n['ext'] = list(ext)
    if oq: n['open_questions'] = list(oq)
    return n

